```pseudocode
// Function to perform binary search on a sorted array
// Input:
//   sorted_array: A list or array of elements sorted in ascending order.
//   target: The element to search for within the sorted_array.
// Output:
//   The index of the target element if found, otherwise -1.

FUNCTION binary_search(sorted_array, target)

  // Initialize the lower and upper bounds of the search space
  low = 0
  high = length(sorted_array) - 1

  // Loop while the search space is valid (low is less than or equal to high)
  WHILE low <= high DO

    // Calculate the middle index of the current search space.
    // Using integer division to ensure a whole number index.
    mid = floor((low + high) / 2)

    // Get the element at the middle index
    mid_element = sorted_array[mid]

    // Compare the middle element with the target
    IF mid_element == target THEN
      // Target found! Return its index.
      RETURN mid
    ELSE IF mid_element < target THEN
      // The target is in the right half of the current search space.
      // Discard the left half and the middle element by updating 'low'.
      low = mid + 1
    ELSE // mid_element > target
      // The target is in the left half of the current search space.
      // Discard the right half and the middle element by updating 'high'.
      high = mid - 1
    END IF

  END WHILE

  // If the loop finishes without finding the target, it means the target is not in the array.
  RETURN -1

END FUNCTION

// Example Usage:
// my_list = [2, 5, 8, 12, 16, 23, 38, 56, 72, 91]
// element_to_find = 23
