const validationResult1 = validateEmail(email1);
console.log(`Email: ${email1}, Result: ${JSON.stringify(validationResult1)}`);
// Expected output: Email: test.user+alias@example.com, Result: {"isValid":true,"message":"Email address is valid."}

// Example 2: Invalid email - empty
const email2 = "";
const validationResult2 = validateEmail(email2);
console.log(`Email: "${email2}", Result: ${JSON.stringify(validationResult2)}`);
// Expected output: Email: "", Result: {"isValid":false,"message":"Email address cannot be empty."}

// Example 3: Invalid email - missing "@"
