console.log(`Email: ${email3}, Result: ${JSON.stringify(validationResult3)}`);
// Expected output: Email: testexample.com, Result: {"isValid":false,"message":"Invalid email format. Please include '@' and a '.' after it."}

// Example 4: Invalid email - "@" after "."
