        CosmicMap nebulaMap(1000000); // A million celestial bodies, should be fine.
        std::cout << "Nebula charted successfully!" << std::endl;

        std::cout << "\n--- Attempting to chart a supernova-sized collection of stars ---" << std::endl;
        // This is where the previous program failed. Our new design should be more robust.
        CosmicMap starClusterMap(500000000); // A colossal number.
        std::cout << "Supernova cluster charted successfully!" << std::endl;

    } catch (const std::bad_alloc& e) {
        // This catch block is still important for very low-level allocation failures.
        std::cerr << "A cosmic calamity! The Grand Bazaar of Bytes has spoken: ";
        std::cerr << "Memory allocation failed at the deepest level: " << e.what() << std::endl;
        std::cerr << "Our Cartographer is stranded, unable to chart the infinite expanse." << std::endl;
    } catch (const std::runtime_error& e) {
        std::cerr << "Cosmic anomaly detected: " << e.what() << std::endl;
        std::cerr << "The Cartographer had to abandon this grand venture due to resource limitations." << std::endl;
    } catch (const std::exception& e) {
        std::cerr << "An unexpected cosmic anomaly occurred: " << e.what() << std::endl;
    }

    std::cout << "\nThe Grand Bazaar of Bytes hums on, ever ready for new ventures." << std::endl;
    return 0;
}
